<script setup lang="ts">
import {onUnmounted,ref,watch} from 'vue'
import {ElMessage} from 'element-plus'
import {api} from '../api'
const props=defineProps<{storeId:string}>(),emit=defineEmits<{updated:[]}>()
const busy=ref(false),jobId=ref(''),progress=ref(0),last=ref<any>(),error=ref('')
let sequence=0,timer:ReturnType<typeof setTimeout>|undefined
function stop(){if(timer)clearTimeout(timer);timer=undefined}
async function reload(n=sequence){if(!props.storeId)return;const value=await api.get<any>(`/pod/wb/stores/${props.storeId}/sync-status`);if(n!==sequence)return;last.value=value;if(value.active_job_id){jobId.value=value.active_job_id;busy.value=true;void poll(n)}}
async function poll(n:number){stop();if(n!==sequence||!jobId.value)return;try{const job=await api.get<any>(`/jobs/${jobId.value}`);if(n!==sequence)return;progress.value=Number(job.progress)||0;if(['completed','failed','cancelled','action_required'].includes(job.status)){busy.value=false;jobId.value='';if(job.status==='completed'){await reload(n);emit('updated');if(last.value?.warnings?.length||last.value?.summary?.unknown||last.value?.summary?.ambiguous)ElMessage.warning('商品身份已同步，部分状态未能核验，请查看同步提示和报告');else ElMessage.success('店铺商品、库存、价格折扣已同步匹配')}else{error.value=job.error_message||'同步未完成，请查看原任务后人工重试';await reload(n)}return}}catch(e:any){if(n===sequence)error.value=e.message||'同步进度暂时无法读取'}if(n===sequence&&jobId.value)timer=setTimeout(()=>{void poll(n)},5000)}
async function start(refresh=false){if(!props.storeId||busy.value)return;const n=sequence;busy.value=true;error.value='';try{const value=await api.post<any>(`/pod/wb/stores/${props.storeId}/sync?refresh=${refresh}`);if(n!==sequence)return;if(value.cached){await reload(n);busy.value=false;emit('updated');ElMessage.info('复用5分钟内已完成的同步结果；需要立即重读可点“强制刷新”')}else{jobId.value=value.job_id;progress.value=0;void poll(n)}}catch(e:any){if(n===sequence){error.value=e.message||'无法建立同步任务';busy.value=false;ElMessage.error(error.value)}}}
watch(()=>props.storeId,()=>{sequence++;stop();jobId.value='';busy.value=false;last.value=undefined;error.value='';if(props.storeId)void reload().catch(e=>{error.value=e.message})},{immediate:true})
onUnmounted(()=>{sequence++;stop()})
</script>
<template><div class="wb-sync"><div class="sync-actions"><el-button type="primary" plain :disabled="!storeId" :loading="busy" @click="start()">{{last?.warnings?.length?"继续店铺同步":"店铺同步"}}</el-button><el-button v-if="last?.synced_at" link :disabled="busy" @click="start(true)">强制刷新</el-button><RouterLink v-if="jobId" :to="`/jobs?job=${jobId}`">查看同步进度</RouterLink><el-progress v-if="busy" :percentage="Math.min(100,progress)" style="width:150px"/></div><small v-if="last?.summary">最近同步 {{new Date(last.synced_at).toLocaleString()}} · 可上架 {{last.summary.available_variants}} 个规格 · 匹配 {{last.summary.matched_variants}} 个规格 · 待库存 {{last.summary.pending_stock}} · 待价格折扣 {{last.summary.pending_price}} · 已完成 {{last.summary.completed}}<span v-if="last.summary.released_tasks"> · 已释放 {{last.summary.released_tasks}} 个旧任务</span><span v-if="last.summary.preserved_active"> · 保留 {{last.summary.preserved_active}} 个正在执行的商品</span> · 待核验 {{(last.summary.unknown||0)+(last.summary.ambiguous||0)}}<a v-if="last.job_id" :href="`/api/v1/pod/wb/history/${last.job_id}/report`" target="_blank" rel="noopener"> 下载匹配报告</a></small><small v-for="warning in last?.warnings||[]" :key="warning" class="warning">{{warning}}</small><small v-if="error" class="warning">{{error}}</small></div></template>
<style scoped>.wb-sync{display:flex;flex-direction:column;gap:5px}.sync-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.wb-sync small{color:#62748b}.wb-sync .warning{color:#b45309}</style>
